DROP TABLE Purchase;
DROP TABLE Customer;
DROP TABLE Item;
DROP TABLE Category;
DROP TABLE Supplier;
CREATE TABLE Supplier (SupID INT PRIMARY KEY, SupName VARCHAR(50), City VARCHAR(50));
CREATE TABLE Category (CatID INT PRIMARY KEY, CatName VARCHAR(50));
CREATE TABLE Item (ItemID INT PRIMARY KEY, ItemName VARCHAR(50), Price FLOAT, SupID INT, CatID INT, FOREIGN KEY (SupID) REFERENCES Supplier(SupID), FOREIGN KEY (CatID) REFERENCES Category(CatID));
CREATE TABLE Customer (CustID INT PRIMARY KEY, CustName VARCHAR(50), City VARCHAR(50));
CREATE TABLE Purchase (PurchaseID INT PRIMARY KEY, ItemID INT, CustID INT, Quantity INT, OrderDate VARCHAR(16), FOREIGN KEY (ItemID) REFERENCES Item(ItemID), FOREIGN KEY (CustID) REFERENCES Customer(CustID));
